import pandas as pd

def find_top_scoring_students(students: pd.DataFrame, courses: pd.DataFrame, enrollments: pd.DataFrame) -> pd.DataFrame:
    if students.empty or courses.empty:
        return pd.DataFrame(columns=['student_id'])

    stud_courses = students.merge(courses, on='major', suffixes=('_student', '_course'))
    merged = stud_courses.merge(enrollments, on=['student_id', 'course_id'], how='left')

    def is_top(group):
        total_req = len(group)
        a_grades = (group['grade'] == 'A').sum()
        return total_req == a_grades

    res_ids = []
    for sid, grp in merged.groupby('student_id'):
        if is_top(grp):
            res_ids.append(sid)

    res = pd.DataFrame({'student_id': res_ids})
    return res.sort_values(by='student_id').reset_index(drop=True)
